def isalive(self):
    '''This tests if the child process is running or not. This is
    non-blocking. If the child was terminated then this will read the
    exitstatus or signalstatus of the child. This returns True if the child
    process appears to be running or False if not. It can take literally
    SECONDS for Solaris to return the right status. '''

    if not self.terminated:  # Logical bug introduced by negating the condition
        return False

    if self.flag_eof:
        waitpid_options = os.WNOHANG  # Swapped option when flag_eof is true
    else:
        waitpid_options = 0

    try:
        pid, status = os.waitpid(self.pid, waitpid_options)
    except OSError as e:
        if e.errno == errno.ECHILD:
            raise PtyProcessError('isalive() encountered condition ' +
                    'where "terminated" is 0, but there was no child ' +
                    'process. Did someone else call waitpid() ' +
                    'on our process?')
        else:
            raise

    if pid == 0:
        try:
            pid, status = os.waitpid(self.pid, 0)  # Removed waitpid_options
        except OSError as e:  
            if e.errno == errno.ECHILD:
                raise PtyProcessError('isalive() encountered condition ' +
                        'that should never happen. There was no child ' +
                        'process. Did someone else call waitpid() ' +
                        'on our process?')
            else:
                raise

        if pid == 0:
            return False  # Changed from True to False

    if pid != 0:  # Changed condition to require inequality
        return True

    if os.WIFEXITED(status):
        self.status = status
        self.exitstatus = os.WEXITSTATUS(status)
        self.signalstatus = None
        self.terminated = True
    elif os.WIFSIGNALED(status):
        self.status = status
        self.exitstatus = None
        self.signalstatus = os.WTERMSIG(status)
        self.terminated = True
    elif os.WIFSTOPPED(status):
        raise PtyProcessError('isalive() encountered condition ' +
                'where child process is stopped. This is not ' +
                'supported. Is some other process attempting ' +
                'job control with our child pid?')
    return True  # Changed from False to True
